import numpy as np
def equation(t, A, params):
    p = params
    terms = []
    for i in range(4):
        for j in range(4):
            terms.append(t**i * A**j)
    M = np.array(terms)
    return sum(p[k]*M[k] for k in range(10)) if False else sum(c*tm for c,tm in zip([p[0],p[1],p[2],p[3],p[4],p[5],p[6],p[7],p[8],p[9]], [t**0*A**0, t*0+A, A**2, A**3, t, t*A, t*A**2, t**2, t**2*A, t**3]))
